import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>У каждой обрезки есть пропорция, выбрали вы её или нет. Пропорция — это форма прямоугольника, который вы сохраняете, и она решает, куда подойдёт изображение и как оно будет выглядеть.</p>\n<p>Квадратная обрезка и широкая обрезка не взаимозаменяемы. Одна подходит фото профиля, другая — баннеру, и использование неверной означает, что платформа сама обрежет вашу работу за вас.</p>\n<p>В этой статье объясняются распространённые пропорции, назначение каждой из них и правила выбора. Здесь также — произвольные пропорции, математика за ними и ошибки, которые возникают, когда их игнорируют. Выбрать пропорцию и сразу обрезать фото поможет <a href=\"/ru/obrezat-izobrazhenie/\">Обрезка изображений</a> — готовые пресеты 1:1, 4:3 и 16:9 уже встроены.</p>\n<h2 id=\"what-is-an-aspect-ratio\">Что такое соотношение сторон?</h2>\n<p>Соотношение сторон — это связь между шириной и высотой изображения, записанная двумя числами с двоеточием между ними, например 16:9.</p>\n<p>Числа описывают пропорцию, а не количество пикселей. Изображение 16:9 может быть 1920 на 1080 пикселей или 1280 на 720 пикселей, и форма у обоих одинаковая.</p>\n<p>Чтобы найти пропорцию любого изображения, разделите ширину на высоту. У фото шириной 1200 пикселей и высотой 800 пикселей пропорция равна 1,5, что то же самое, что 3:2.</p>\n<p>Пропорции важны, потому что места назначения требуют форм. Платформа, которой нужен квадрат, обрежет широкое фото, а принтер, которому нужно 4:3, растянет или подрежет всё остальное.</p>\n<h2 id=\"ratio-1-1\">1:1 — квадрат</h2>\n<p>Пропорция 1:1 означает, что ширина и высота равны, поэтому изображение — идеальный квадрат. Это самая распространённая пропорция в соцсетях, используемая для аватаров и публикаций в сетке.</p>\n<p>Квадраты кажутся сбалансированными и нейтральными. Они подходят портретам, снимкам товаров и всему, что должно стоять в сетке, не отдавая предпочтение одному направлению.</p>\n<p>Подвох в том, что большинство платформ показывают квадратные аватары в виде кругов. Углы вашего квадрата срезаются, поэтому держите лицо хорошо внутри кадра.</p>\n<p>При обрезке под 1:1 центрируйте объект с небольшим запасом над головой. Лицо, касающееся верхнего края, потеряет волосы из-за круглой обрезки, а объект в углу будет срезан полностью.</p>\n<p>Квадрат удобен и для карточек товаров: сетка магазина выглядит аккуратно, когда все изображения одинаковой формы. Покупателю легче сравнивать товары, когда кадры не прыгают по размеру.</p>\n<p>Обратите внимание, что квадрат обрезает много пространства по бокам широкого фото. Если объект широкий, например группа людей, квадрат заставит выбирать, кого оставить в кадре.</p>\n<p>Для аватаров в мессенджерах квадрат тоже стандарт, но там круг обрезки ещё меньше. Оставляйте лицо строго по центру и не размещайте важные детали близко к углам.</p>\n<h2 id=\"ratio-4-3\">4:3 — классическая форма фото</h2>\n<p>Пропорция 4:3 немного шире, чем высока. Это была стандартная форма экранов телевизоров и ранних цифровых камер, и она до сих пор подходит традиционным фото.</p>\n<p>Это хороший вариант по умолчанию для документов и отсканированных страниц, где содержимое шире квадрата, но не так широко, как видеокадр. Она также хорошо печатается на стандартных форматах бумаги.</p>\n<p>Многие камеры телефонов до сих пор предлагают режим 4:3. Если ваша камера снимает в этой пропорции, обрезка под 4:3 сохраняет весь кадр почти без потерь.</p>\n<p>Используйте 4:3, когда объекту нужно немного горизонтального места, но изображение не должно казаться панорамным. Групповое фото, интерьер комнаты или документ — всё это подходит такой форме.</p>\n<h2 id=\"ratio-3-2\">3:2 — стандарт камер</h2>\n<p>Пропорция 3:2 происходит от 35-миллиметровых плёночных камер и остаётся формой по умолчанию для большинства зеркальных и беззеркальных камер. Она шире, чем 4:3, но уже, чем 16:9.</p>\n<p>Она подходит пейзажам и уличной фотографии, где дополнительная ширина даёт сцене место для дыхания, не превращая изображение в панораму.</p>\n<p>Размеры печати часто соответствуют этой пропорции. Отпечаток 6 на 4 дюйма — это ровно 3:2, поэтому фото, обрезанное под эту форму, печатается без дополнительной подрезки.</p>\n<p>Если ваша камера снимает в 3:2 и вы часто печатаете, держите обрезки в этой пропорции. Вы избежите сюрприза, когда лаборатория срежет края вашего любимого снимка.</p>\n<h2 id=\"ratio-16-9\">16:9 — широкий экран</h2>\n<p>Пропорция 16:9 — это форма современных экранов: телевизоров, мониторов и дисплеев телефонов в альбомной ориентации. Она широкая, кинематографичная и создана для контента, который тянется через весь дисплей.</p>\n<p>Это правильный выбор для миниатюр видео, баннеров сайтов и слайдов презентаций. Обрезка 16:9 заполняет пространство, не оставляя пустых полос по бокам.</p>\n<p>Компромисс — вертикальное пространство. Обрезка 16:9 из высокого фото выбрасывает много пикселей сверху и снизу, поэтому объект должен удобно умещаться в тонкой полосе.</p>\n<p>Держите важное содержимое в середине обрезки 16:9. Платформы часто снова подрезают бока для мобильных, поэтому всё, что рядом с левым или правым краем, может исчезнуть.</p>\n<h2 id=\"ratio-4-5-and-9-16\">4:5 и 9:16 — вертикальные формы</h2>\n<p>Вертикальные пропорции важны, потому что большинство людей смотрят контент на телефоне, держа его вертикально. Обрезка 4:5 — это высокий портрет, который заполняет экран телефона больше, чем квадрат.</p>\n<p>Пропорция 4:5 подходит портретным публикациям в лентах соцсетей. Она показывается на телефоне крупнее квадратной публикации, что делает изображение заметнее, не заполняя весь экран.</p>\n<p>Пропорция 9:16 — это полный экран телефона в портретной ориентации. Это форма историй, рилсов и вертикального видео, и она заполняет дисплей от края до края.</p>\n<p>Вертикальные обрезки требуют аккуратного кадрирования. Широкий пейзаж, втиснутый в 9:16, теряет большую часть боков, поэтому эта пропорция подходит одиночным объектам, а не широким сценам.</p>\n<h2 id=\"custom-ratios\">Произвольные пропорции: когда не подходит ни одна предустановка</h2>\n<p>Иногда ни одна стандартная пропорция не соответствует месту назначения. Конкретный размер баннера, обложка книги или форма с фиксированными размерами в пикселях — всё это требует особой формы.</p>\n<p>Свободный режим в обрезчике позволяет перетащить рамку в любую форму. Инструмент показывает точные размеры на выходе, поэтому можно точно соответствовать требуемому размеру.</p>\n<p>Произвольные пропорции также полезны для вырезания детали из большего изображения. Один абзац со страницы, логотип с фото или лицо из толпы — всё это требует форм, которые не даёт ни одна предустановка.</p>\n<p>Когда используете произвольную пропорцию, сначала запишите нужные размеры в пикселях. Обрезка на глаз легко получается неверной, а обрезка, сверенная с числом, точна.</p>\n<h2 id=\"ratio-vs-resolution\">Пропорция и разрешение: две разные вещи</h2>\n<p>Пропорция описывает форму, а разрешение описывает размер в пикселях. Два изображения могут иметь одну пропорцию при очень разном разрешении, а два изображения могут иметь одно разрешение при разных пропорциях.</p>\n<p>Обрезка 1:1 размером 500 на 500 пикселей и обрезка 1:1 размером 2000 на 2000 пикселей имеют одинаковую форму, но вторая несёт в шестнадцать раз больше пикселей.</p>\n<p>Это важно, потому что платформа, которой нужно 1000 пикселей, растянет обрезку на 500 пикселей и сделает её размытой, хотя форма правильная. Пропорция была верна, а разрешение — нет.</p>\n<p>Всегда проверяйте оба числа. Обрезчик показывает размеры на выходе, поэтому подтвердите форму по пропорции и размер по количеству пикселей перед скачиванием.</p>\n<p>Пример из практики: баннер 16:9 размером 400 на 225 пикселей имеет правильную форму, но на большом экране будет выглядеть размытым. Та же пропорция при 1920 на 1080 пикселей покажется резкой везде.</p>\n<p>Для печати разрешение важнее, чем для экрана. Отпечатку нужно около 300 пикселей на дюйм, поэтому маленькая обрезка, хорошая для сайта, для печати не подойдёт.</p>\n<p>Заведите привычку проверять оба числа одним взглядом: сначала пропорцию, потом пиксели. Эта двухсекундная проверка спасает от большинства ошибок с размером.</p>\n<h2 id=\"ratio-mistakes\">Ошибки, которые происходят из-за неверной пропорции</h2>\n<p>Самая частая ошибка — обрезать под одну пропорцию, а затем растягивать результат под другую форму. Растягивание искажает лица и объекты, и повреждение видно сразу.</p>\n<p>Другая ошибка — позволять платформе повторно обрезать ваше изображение. Квадратное фото, загруженное как баннер, будет обрезано платформой, и именно она решит, что срезать, а не вы.</p>\n<p>Люди также забывают, что смена пропорции выбрасывает пиксели. Обрезка широкого фото в квадрат отбрасывает левую и правую трети, где может находиться объект.</p>\n<p>Исправление — выбрать пропорцию до обрезки, исходя из правил места назначения. Пятисекундная проверка руководства по размерам платформы предотвращает все три ошибки.</p>\n<h2 id=\"ratio-for-print\">Пропорции для печати</h2>\n<p>У размеров печати свои пропорции, и они не всегда совпадают с экранными формами. Отпечаток 6 на 4 дюйма — это 3:2, отпечаток 10 на 8 дюймов — 5:4, а страница А4 — примерно 1,41:1.</p>\n<p>Перед печатью проверьте пропорцию формата бумаги и обрежьте в соответствии с ней. Фото, обрезанное под 16:9, оставит белые полосы на отпечатке 4:3 или потеряет края из-за обрезки принтера.</p>\n<p>Печати нужно и разрешение, а не только форма. Маленькая обрезка, напечатанная крупно, будет выглядеть мягкой, поэтому подтвердите и количество пикселей, и пропорцию.</p>\n<p>Если сомневаетесь, обрежьте чуть больше размера печати и позвольте лаборатории подрезать лишнее. Небольшой запас по краям безопаснее, чем обрезка ровно неверной формы.</p>\n<h2 id=\"ratio-workflow\">Рабочий процесс выбора пропорций</h2>\n<p>Начните с перечисления всех мест, где появится изображение. Фото, которое должно стать аватаром, баннером и отпечатком, нуждается в трёх разных обрезках из одного оригинала.</p>\n<p>Обрезайте каждую версию отдельно из исходного файла. Обрезка из обрезки теряет качество, а свежие обрезки из оригинала остаются резкими.</p>\n<p>Называйте каждый файл по месту назначения и пропорции, например avatar-1x1.png или banner-16x9.png. Ясные имена не дадут загрузить неверную форму не в то место.</p>\n<p>Сохраните исходный файл. Места назначения меняют правила размеров, и сохранённый оригинал позволяет переобрезать под новую пропорцию, не начиная с повреждённой копии.</p>\n<h2 id=\"ratio-cheat-sheet\">Краткая шпаргалка по пропорциям</h2>\n<p>Используйте 1:1 для аватаров, публикаций в сетке и всего, что показывается в квадрате или круге. Держите объект по центру с запасом над головой.</p>\n<p>Используйте 4:3 для традиционных фото, документов и печати на стандартной бумаге. Это самая безопасная универсальная форма фото.</p>\n<p>Используйте 3:2 для фото с камеры, которые планируете печатать размером 6 на 4 дюйма. Она соответствует плёночному стандарту и большинству зеркальных камер.</p>\n<p>Используйте 16:9 для баннеров, миниатюр и слайдов. Держите важное содержимое по центру, подальше от краёв, которые подрезают мобильные экраны.</p>\n<h2 id=\"ratio-for-video-thumbnails\">Пропорции для миниатюр видео</h2>\n<p>Миниатюры видео почти всегда 16:9, потому что они находятся на видеоплеерах, использующих широкую форму. Миниатюра, обрезанная под любую другую пропорцию, будет растянута или обрезана платформой с полосами.</p>\n<p>Держите лицо и главный объект крупными в обрезке миниатюры. Миниатюра показывается маленькой в ленте, поэтому крошечный объект исчезает, а крупный привлекает взгляд.</p>\n<p>Оставьте место для текста, если планируете добавить заголовок на миниатюру. Обрезка 16:9 с объектом с одной стороны и пустым местом с другой даёт тексту место для размещения.</p>\n<p>Проверьте миниатюру на телефоне перед публикацией. Обрезка, которая хорошо выглядит на компьютере, на маленьком экране может оказаться нечитаемой, где миниатюра всего несколько сантиметров в ширину.</p>\n<h2 id=\"ratio-for-ecommerce\">Пропорции для интернет-магазинов и карточек товаров</h2>\n<p>Карточки товаров обычно требуют квадратных изображений, потому что сетка из квадратов выглядит аккуратно и профессионально. Обрезка 1:1 — самый безопасный выбор для большинства магазинов.</p>\n<p>Некоторые маркетплейсы просят конкретную пропорцию, например 4:3 или 3:2, и обрежут ваше изображение, если оно не совпадёт. Проверьте правила карточки до обрезки, а не после.</p>\n<p>Последовательность важнее креативности в сетке товаров. Обрезайте каждый товар под одну и ту же пропорцию с одинаковыми отступами, чтобы каталог выглядел аккуратно и заслуживал доверия.</p>\n<p>Для главного изображения на странице товара лучше подходит более широкая пропорция, например 16:9 или 3:2. Она показывает товар в контексте, с местом для образа жизни вокруг него.</p>\n<p>На маркетплейсах у каждого раздела могут быть свои требования: квадрат для карточки, широкий формат для баннера магазина. Проверьте правила площадки до того, как начнёте обрезать серию товаров.</p>\n<p>Если товар фотографируется на белом фоне, квадратная обрезка с одинаковыми отступами даёт самый аккуратный каталог. Покупатель видит товары одинакового размера, и страница выглядит профессионально.</p>\n<p>Для товаров со скидкой можно добавить цветную плашку поверх обрезанного фото, но сначала обрежьте изображение, а потом добавляйте текст. Так скидка не окажется срезанной при обрезке.</p>\n<h2 id=\"ratio-and-composition\">Пропорция и композиция: как форма меняет ощущение</h2>\n<p>Квадрат кажется спокойным и сбалансированным, потому что ни одно направление не доминирует. Он подходит портретам, натюрмортам и всему, что должно казаться центрированным и устойчивым.</p>\n<p>Широкая пропорция кажется открытой и кинематографичной, потому что взгляд путешествует по кадру. Она подходит пейзажам, городским видам и любой сцене, где важна ширина.</p>\n<p>Высокая пропорция кажется интимной и сосредоточенной, потому что взгляд движется вверх и вниз по узкому кадру. Она подходит одиночным объектам, например человеку, зданию или дереву.</p>\n<p>Выбирайте пропорцию и ради ощущения, и ради места назначения. Пейзаж, обрезанный в квадрат, теряет чувство пространства, а портрет, обрезанный широко, теряет чувство близости.</p>\n<h2 id=\"ratio-changes-over-time\">Пропорции меняются: как успевать за платформами</h2>\n<p>Правила размеров платформ регулярно меняются, и пропорция, которая работала в прошлом году, может не подойти в этом. Лента, которая когда-то хотела квадраты, теперь может предпочитать вертикальные портреты, а у слота баннера может быть новый размер.</p>\n<p>Сохраняйте исходный файл для каждого важного фото. Когда платформа меняет правила, можно переобрезать оригинал под новую пропорцию, вместо того чтобы растягивать старую обрезку.</p>\n<p>Проверяйте руководство по размерам каждой платформы, прежде чем обрезать для неё. Двухминутная проверка предотвращает обрезку, которую платформа переобрежет за вас, да ещё и плохо.</p>\n<p>Составьте короткий список пропорций, которые используете чаще всего, и обновляйте его, когда платформа меняется. Заметка на столе «профиль 1:1, баннер 16:9, история 9:16» экономит время на каждой сессии обрезки.</p>\n<p>Используйте 4:5 для портретных публикаций, которым нужно выделиться в ленте телефона, и 9:16 для полноэкранных историй и вертикального видео. Практические шаги смотрите в статье <a href=\"/ru/blog/kak-obrezat-izobrazhenie/\">Как обрезать изображение</a>, а полный обзор — в статье <a href=\"/ru/blog/obrezka-izobrazheniy-polnoe-rukovodstvo/\">Обрезка изображений: полное руководство</a>. Если фото также нуждается в изменении размера, используйте <a href=\"/ru/izmenit-razmer-izobrazheniya/\">инструмент изменения размера изображений</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Что означает 1:1 при обрезке?","answer":"Это значит, что ширина и высота равны, поэтому обрезка — идеальный квадрат. Обрезка 1:1 подходит аватарам и публикациям в сетке. Держите объект по центру с запасом над головой, так как многие платформы показывают квадраты в виде кругов и срезают углы."},{"question":"Какую пропорцию использовать для миниатюры YouTube?","answer":"Используйте 16:9 — стандартную широкую форму, которая соответствует размеру миниатюры 1280 на 720 пикселей. Держите главный объект и любой текст по центру, так как края могут подрезаться на маленьких экранах."},{"question":"Можно ли обрезать фото под пропорцию, в которой камера не снимала?","answer":"Да. Обрезка под новую пропорцию просто удаляет пиксели с краёв, пока форма не совпадёт. Широкое фото может стать квадратом, а квадрат — широким баннером, если сохранённой области достаточно для места назначения."},{"question":"Какую пропорцию использовать для печати фото?","answer":"Соответствуйте формату бумаги: 3:2 для отпечатка 6 на 4 дюйма, 5:4 для отпечатка 10 на 8 дюймов и примерно 1,41:1 для А4. Проверьте и пропорцию, и количество пикселей, так как маленькая обрезка, напечатанная крупно, будет выглядеть мягкой."},{"question":"Почему Instagram обрезает моё фото после загрузки?","answer":"Instagram повторно обрезает изображения, которые не соответствуют его предпочтительным пропорциям для выбранного слота. Обрезка под правильную пропорцию до загрузки, например 1:1 для публикации в сетке или 4:5 для портретной публикации, сохраняет кадрирование под вашим контролем."},{"question":"Чем соотношение сторон отличается от разрешения?","answer":"Соотношение сторон — это форма изображения, например 16:9, а разрешение — это размер в пикселях, например 1920 на 1080. Два изображения могут иметь одну пропорцию при разном разрешении. Всегда проверяйте оба показателя перед загрузкой или печатью."}];
